/**
 * Phase 4 independent evaluation scenarios.
 *
 * Issuer-disjoint and document-disjoint from the Phase 3 benchmark-suite package.
 * Ground truth is authored offline — never generated by compareProvisions().
 * Prefer authentic corpus slices when available; otherwise synthetic authentic-style text.
 */
import { getDefaultCorpus } from "../corpus";
import { sha256Hex } from "../hash";
import type { ComparableCovenantFamily, PrecedentProvision } from "../types";
import type { BenchmarkCategory, BenchmarkGroundTruth, BenchmarkScenario, BenchmarkSplit } from "./types";

function synth(
  id: string,
  family: ComparableCovenantFamily,
  sourceText: string,
  extras: Partial<PrecedentProvision> & { issuerId: string; documentId: string },
): PrecedentProvision {
  return {
    provisionId: id,
    covenantFamily: family,
    sourceText,
    sourceVersionHash: sha256Hex(sourceText),
    locator: {
      packageId: `p4-${extras.issuerId}`,
      documentId: extras.documentId,
      sourcePath: extras.locator?.sourcePath ?? "lib/precedent-comparison/benchmark/phase4-scenarios.ts",
      sourceSectionRef: extras.locator?.sourceSectionRef ?? id,
      charStart: extras.locator?.charStart ?? 0,
      charEnd: extras.locator?.charEnd ?? sourceText.length,
    },
    documentRole: extras.documentRole ?? "ORIGINAL",
    agreementType: extras.agreementType ?? "CREDIT_AGREEMENT",
    issuerId: extras.issuerId,
    amendsProvisionId: extras.amendsProvisionId ?? null,
    tags: extras.tags ?? ["phase4-benchmark"],
    reviewStatus: "SOURCE_ONLY",
    reviewedBy: null,
    reviewNote: null,
    financialDefinitionTerms: extras.financialDefinitionTerms ?? [],
    evalIsolation: "NONE",
  };
}

function gt(partial: BenchmarkGroundTruth): BenchmarkGroundTruth {
  return partial;
}

function sc(
  id: string,
  split: BenchmarkSplit,
  category: BenchmarkCategory,
  family: ComparableCovenantFamily,
  left: PrecedentProvision,
  right: PrecedentProvision,
  groundTruth: BenchmarkGroundTruth,
  overlays?: { left?: string; right?: string },
): BenchmarkScenario {
  return {
    id,
    split,
    category,
    covenantFamily: family,
    left,
    right,
    leftDefinitionOverlay: overlays?.left,
    rightDefinitionOverlay: overlays?.right,
    groundTruth,
  };
}

/** Pull a real corpus provision by predicate; fall back to synthetic. */
function fromCorpus(
  pred: (p: PrecedentProvision) => boolean,
  fallback: PrecedentProvision,
): PrecedentProvision {
  try {
    const hit = getDefaultCorpus().list().find(pred);
    if (!hit) return fallback;
    return {
      ...hit,
      provisionId: fallback.provisionId,
      tags: [...hit.tags, "phase4-authentic-slice"],
      evalIsolation: "NONE",
    };
  } catch {
    return fallback;
  }
}

const ISSUERS = [
  "p4-aurora",
  "p4-bristle",
  "p4-cascade",
  "p4-drift",
  "p4-ember",
  "p4-flint",
  "p4-granite",
  "p4-harbor",
  "p4-ivory",
  "p4-jasper",
] as const;

function mkPair(
  id: string,
  split: BenchmarkSplit,
  category: BenchmarkCategory,
  family: ComparableCovenantFamily,
  issuerIdx: number,
  leftText: string,
  rightText: string,
  truth: BenchmarkGroundTruth,
  opts?: { rightRole?: "AMENDMENT"; overlays?: { left?: string; right?: string } },
): BenchmarkScenario {
  const issuer = ISSUERS[issuerIdx % ISSUERS.length]!;
  const docL = `${issuer}-doc-a`;
  const docR = opts?.rightRole === "AMENDMENT" ? `${issuer}-doc-amd` : `${issuer}-doc-b`;
  const left = synth(`${id}-L`, family, leftText, { issuerId: issuer, documentId: docL });
  const right = synth(`${id}-R`, family, rightText, {
    issuerId: issuer,
    documentId: docR,
    documentRole: opts?.rightRole ?? "ORIGINAL",
    agreementType: opts?.rightRole === "AMENDMENT" ? "AMENDMENT" : "CREDIT_AGREEMENT",
    amendsProvisionId: opts?.rightRole === "AMENDMENT" ? `${id}-L` : null,
  });
  return sc(id, split, category, family, left, right, truth, opts?.overlays);
}

