let i = 0;
for (const s of SEEDS) {
  const scenario = mkPair(
    s.id,
    s.split,
    s.cat,
    s.fam,
    i++,
    s.left,
    s.right,
    gt({
      textualDifference: s.textDiff,
      materialLegalDifference: s.material,
      legallyEquivalentDespiteText: s.cat === "TEXTUALLY_DIFFERENT_LEGALLY_EQUIVALENT",
      identicalTextDifferentDefinitions: s.cat === "IDENTICAL_TEXT_DIFFERENT_DEFINITIONS",
      expectedMaterialDimensions: s.material ? ["STRUCTURE"] : [],
      controllingContextComplete:
        s.cat !== "MISSING_CONTROLLING_DEFINITIONS" &&
        s.cat !== "IDENTICAL_TEXT_DIFFERENT_DEFINITIONS" &&
        s.cat !== "CROSS_DOCUMENT_RESTRICTION",
      amendmentVersionMatters: !!s.amd,
      mustRefuseUnsupportedConclusion: true,
      authorNote: s.note,
    }),
    { rightRole: s.amd ? "AMENDMENT" : undefined, overlays: s.overlays },
  );
  // Prefer authentic text slices while preserving Phase-4 issuer/document identity
  if (s.fam === "INDEBTEDNESS" && s.split === "DEV" && s.id.endsWith("01")) {
    const authentic = fromCorpus(
      (p) => p.covenantFamily === "INDEBTEDNESS" && p.issuerId === "chwy" && p.sourceText.length > 200 && !p.tags.includes("basket"),
      scenario.left,
    );
    if (authentic.locator.sourcePath.includes("unseen-packages")) {
      scenario.left = {
        ...scenario.left,
        sourceText: authentic.sourceText.slice(0, 1200),
        sourceVersionHash: sha256Hex(authentic.sourceText.slice(0, 1200)),
        tags: [...scenario.left.tags, "phase4-authentic-text"],
        locator: {
          ...scenario.left.locator,
          sourcePath: authentic.locator.sourcePath,
          charStart: authentic.locator.charStart,
          charEnd: Math.min(authentic.locator.charEnd, authentic.locator.charStart + 1200),
          sourceSectionRef: authentic.locator.sourceSectionRef,
        },
      };
    }
  }
  if (s.split === "DEV") PHASE4_DEV_SCENARIOS.push(scenario);
  else PHASE4_HELD_OUT_SCENARIOS.push(scenario);
}

export const ALL_PHASE4_SCENARIOS: BenchmarkScenario[] = [...PHASE4_DEV_SCENARIOS, ...PHASE4_HELD_OUT_SCENARIOS];

export function phase4ScenarioCounts(): { total: number; dev: number; heldOut: number; distinctIssuers: number; distinctDocuments: number } {
  const issuers = new Set(ALL_PHASE4_SCENARIOS.flatMap((s) => [s.left.issuerId, s.right.issuerId]));
  const docs = new Set(ALL_PHASE4_SCENARIOS.flatMap((s) => [s.left.locator.documentId, s.right.locator.documentId]));
  return {
    total: ALL_PHASE4_SCENARIOS.length,
    dev: PHASE4_DEV_SCENARIOS.length,
    heldOut: PHASE4_HELD_OUT_SCENARIOS.length,
    distinctIssuers: issuers.size,
    distinctDocuments: docs.size,
  };
}
